import os,re
from html.parser import HTMLParser

VOID={'meta','link','br','img','hr','input','source'}
class P(HTMLParser):
    def __init__(s):
        super().__init__(convert_charrefs=True); s.stack=[]; s.err=[]
    def handle_starttag(s,t,a):
        if t not in VOID: s.stack.append((t,s.getpos()))
    def handle_endtag(s,t):
        if t in VOID: return
        if not s.stack: s.err.append(f"stray </{t}> at {s.getpos()}"); return
        top,pos=s.stack.pop()
        if top!=t: s.err.append(f"expected </{top}> (opened {pos}) got </{t}> at {s.getpos()}")

pages=[]
for root,d,files in os.walk('.'):
    if '.git' in root: continue
    for f in files:
        if f.endswith('.html'): pages.append(os.path.join(root,f))
ok=True
for p in sorted(pages):
    src=open(p,encoding='utf-8').read()
    pr=P(); pr.feed(src); pr.close()
    unclosed=[f"{t}@{pos}" for t,pos in pr.stack]
    if pr.err or unclosed:
        ok=False
        print(f"FAIL {p}: errs={pr.err} unclosed={unclosed}")
    else:
        print(f"ok   {p}  ({len(src)} bytes)")
print("ALL WELL-FORMED" if ok else "PROBLEMS FOUND")
EOF

